#!/usr/bin/env python3
"""Render the sanitized org chart; no private runtime reads or live API calls."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'agent-org.json').read_text())
e=lambda x:escape(str(x))
cards=''.join('<article class="org-card" data-org-role="'+e(r['id'])+'"><div class="org-label">On demand</div><h3>'+e(r['name'])+'</h3><p>'+e(r['purpose'])+'</p><details><summary>Skills and procedures</summary><ul>'+''.join('<li><code>'+e(s)+'</code></li>' for s in r['skills'])+'</ul></details></article>' for r in d['roles'])
css='''<style>
.org{color:#141715;overflow-wrap:anywhere}.org .org-label{font:700 .68rem ui-monospace,monospace;text-transform:uppercase;letter-spacing:.11em;color:#b8562f}.org h1{font:500 clamp(2rem,5vw,3rem)/1.12 Georgia,serif;letter-spacing:-.02em;margin:12px 0}.org h2{font:500 1.55rem Georgia,serif;margin:28px 0 12px}.org h3{font:500 1.2rem Georgia,serif;margin:7px 0}.org p{line-height:1.6}.org .org-note{background:#f6e3da;border-left:3px solid #b8562f;padding:12px 15px;border-radius:6px}.org .org-boss{max-width:620px;text-align:center;padding:20px;border:1px solid #a5b6a6;border-radius:14px;background:#e8ecd9;margin:20px auto}.org .org-arrow{text-align:center;color:#1d4a3f;font-size:26px}.org .org-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.org .org-card{min-width:0;background:#fffdf7;border:1px solid #d9d7c9;border-radius:12px;padding:20px}.org .org-card p{font-size:.93rem}.org summary{cursor:pointer;font-weight:600}.org code{font-size:.8rem}.org .org-proof{display:grid;grid-template-columns:1fr 1fr;gap:12px}.org ul{padding-left:1.25em}.org li{margin:.5em 0}.org .org-process{padding:14px 18px;background:#e9e5d6;border-radius:10px;font-size:.95rem}.org .org-footer{color:#5f6c63;font-size:.85rem;margin-top:30px}@media(max-width:760px){.org .org-grid{grid-template-columns:1fr}.org .org-proof{grid-template-columns:1fr}}@media print{.org details>*{display:block}}
</style>'''
inner=css+'''<section class="org" aria-label="Jax agent organization"><div class="org-label">Internal operating system · not a customer service launch</div><h1>One front door.<br>A team when the work needs it.</h1>'''+f'<p>{e(d["architecture"])}</p><p class="org-note"><b>Status:</b> {e(d["status"])} · Checked {e(d["updated"])}</p>'+'''<div class="org-boss"><div class="org-label">Owner</div><h3>Evan</h3><p>Relationships, priorities and business commitments.</p></div><div class="org-arrow" aria-hidden="true">↓</div><div class="org-boss"><div class="org-label">Single front door</div><h3>Chief of Staff</h3><p>Understand → retrieve context → route → track → verify → return one result.</p></div><div class="org-arrow" aria-hidden="true">↓</div><div class="org-grid">'''+cards+'</div><h2>How to use it</h2><p>'+e(d['front_door'])+'''</p><div class="org-process"><b>Try:</b> “Jax Chief of Staff: review our current offer and tell me which decisions remain open before launch.”<br><br><b>Or:</b> “Jax: prepare an onboarding and acceptance checklist for our internal operating system.”</div><p>Shared knowledge stays in the existing Jax notes and source library. Relevant procedures load on demand; listing a skill is not a claim that its external integration is connected. Missing facts and business decisions stay visible.</p><h2>What has actually been verified</h2><div class="org-proof">'''+''.join('<div class="org-card"><div class="org-label">'+e(k.replace('_',' '))+'</div><p>'+e(v)+'</p></div>' for k,v in d['proof'].items())+'</div><h2>Boundaries</h2><ul>'+''.join('<li>'+e(v)+'</li>' for v in d['limits'])+'''</ul><p class="org-footer">This is a sanitized capability guide, not a live task dashboard. Real task/client records and model outputs are private. Source inspiration: <a href="https://x.com/godsystemsmd/status/2120157040081338509">thin harness, reusable skills</a>; architecture uses <a href="https://hermes-agent.nousresearch.com/docs/user-guide/features/skills">Hermes skills</a>, existing approved inference and a bounded local control plane. GStack/GBrain were not installed.</p></section>'''
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Agent Organization — Jax Systems</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f0e7;color:#141715;font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1080px;margin:auto;padding:28px 24px 65px}a{color:#1d4a3f;text-underline-offset:3px}header{padding:15px 24px;border-bottom:1px solid #d9d7c9}header>div{max-width:1032px;margin:auto;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}@media(max-width:500px){main{padding:22px 16px}}</style></head><body><header><div><b>Jax Systems</b><a href="./">← Business workspace</a></div></header><main>'''+inner+'</main></body></html>'
(ROOT/'agent-org.html').write_text(page)
index=ROOT/'index.html'
s=index.read_text()
a,b='<!-- JAX AGENT ORG START -->','<!-- JAX AGENT ORG END -->'
if a in s or b in s:
 if s.count(a)!=1 or s.count(b)!=1:raise ValueError('Expected one pair of org markers')
 before,rest=s.split(a,1);_,after=rest.split(b,1)
 index.write_text(before+a+'\n<main class="page" id="page-agents"><div class="wrap">'+inner+'</div></main>\n'+b+after)
print('Rendered sanitized organization: 6 roles; status = '+d['status'])
